function codiconCss(codiconUri: string): string {
	return codiconUri ? `@font-face{font-family:codicon;src:url('${codiconUri}') format('truetype');font-display:block}.codicon{font:normal normal normal 16px/1 codicon;display:inline-block;text-decoration:none;text-rendering:auto;text-align:center;text-transform:none;-webkit-font-smoothing:antialiased;user-select:none}.codicon-settings-gear:before{content:'\\eb51'}.codicon-ellipsis:before{content:'\\ea7c'}.codicon-chevron-left:before{content:'\\eab5'}` : '';
}

