export interface BridgeUiDiffRow {
	kind: 'file' | 'hunk' | 'add' | 'del' | 'ctx' | 'meta' | 'truncated';
	oldLine: number | null;
	newLine: number | null;
	text: string;
}

export function parseUnifiedDiffForUi(value: unknown): BridgeUiDiffRow[] {
	const source = String(value ?? '').replace(/\r\n?|\u2028|\u2029/g, '\n');
	if (!source) return [];
	const rows: BridgeUiDiffRow[] = [];
	let oldLine = 0;
	let newLine = 0;
	for (const raw of source.split('\n')) {
		if (raw.startsWith('@@')) {
			const match = /^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@/.exec(raw);
			if (match) { oldLine = Number(match[1]); newLine = Number(match[3]); }
			rows.push({ kind: 'hunk', oldLine: null, newLine: null, text: raw });
			continue;
		}
		if (raw === '... diff truncated ...') { rows.push({ kind: 'truncated', oldLine: null, newLine: null, text: raw }); continue; }
		if (raw.startsWith('diff --git ') || raw.startsWith('--- ') || raw.startsWith('+++ ')) { rows.push({ kind: 'file', oldLine: null, newLine: null, text: raw }); continue; }
		if (/^(?:index |new file mode |deleted file mode |old mode |new mode |similarity index |dissimilarity index |rename from |rename to |copy from |copy to |\\ No newline at end of file)/.test(raw)) { rows.push({ kind: 'meta', oldLine: null, newLine: null, text: raw }); continue; }
		if (raw.startsWith('+')) { rows.push({ kind: 'add', oldLine: null, newLine, text: raw.slice(1) }); newLine += 1; continue; }
		if (raw.startsWith('-')) { rows.push({ kind: 'del', oldLine, newLine: null, text: raw.slice(1) }); oldLine += 1; continue; }
		if (raw.startsWith(' ')) { rows.push({ kind: 'ctx', oldLine, newLine, text: raw.slice(1) }); oldLine += 1; newLine += 1; continue; }
		rows.push({ kind: 'meta', oldLine: null, newLine: null, text: raw });
	}
	return rows;
}

